package unitary

// Every output field reads the same complete input. Host evaluation is serial;
// no generated byte conditions another field, and no speedup is claimed.
import (
 "bytes"
 "crypto/sha256"
 "encoding/hex"
 "encoding/json"
 "io"
 "sort"
 "strconv"
 "unicode/utf8"
)

const nativeGeneratorSchema="wingless.native-parallel-byte-generator.v1"
const nativeGeneratorSelector="d1f7f462b889e93a9c26a4a619c6e14286b499f3"
const nativeGeneratorEncoding="independent-lsb0-byte-fields-complete-input.v1"
const NativeGeneratorJSONCap=1048576

type nativeGeneratorField struct { Kind string `json:"kind"`; Value int `json:"value"`; Model []byte `json:"model,omitempty"` }
type NativeParallelGenerator struct {
 width int
 exampleCount int
 inputBytes int
 trainingSHA string
 responseHashes []string
 length nativeGeneratorField
 fields []nativeGeneratorField
}
type NativeGenerationResult struct {
 Response *string `json:"response"`
 RawHex string `json:"raw_hex"`
 PredictedLength int `json:"predicted_length"`
 LengthValid bool `json:"length_valid"`
 UTF8Valid bool `json:"utf8_valid"`
 ValidOutput bool `json:"valid_output"`
 CandidateStatus string `json:"candidate_status"`
 SeenTrainingResponse bool `json:"seen_training_response"`
 OutputMode string `json:"output_mode"`
 WholeResponseBank bool `json:"whole_response_bank"`
 LanguageProof bool `json:"language_proof"`
 LengthScores []float64 `json:"length_scores"`
 BitScores [][]float64 `json:"bit_scores"`
}
type nativeGeneratorPayload struct {
 Schema string `json:"schema"`; SourceBlob string `json:"source_blob"`
 SelectorBlob string `json:"selector_blob"`; Encoding string `json:"encoding"`
 Width int `json:"width"`; ExampleCount int `json:"example_count"`; InputBytes int `json:"input_bytes"`
 TrainingSHA string `json:"training_sha256"`; ResponseHashes []string `json:"response_hashes"`
 Length nativeGeneratorField `json:"length"`; Fields []nativeGeneratorField `json:"fields"`
}
type nativeGeneratorEnvelope struct { Payload nativeGeneratorPayload `json:"payload"`; SHA256 string `json:"sha256"` }

func generatorDigest(raw []byte)string{h:=sha256.Sum256(raw);return hex.EncodeToString(h[:])}
func generatorDigestValid(s string)bool{if len(s)!=64{return false};_,err:=hex.DecodeString(s);return err==nil}
func trainGeneratorField(xs []NativeTextExample,labels []string)(nativeGeneratorField,error){
 same:=true;for _,x:=range labels{if x!=labels[0]{same=false}}
 if same{n,err:=strconv.Atoi(labels[0]);return nativeGeneratorField{Kind:"constant",Value:n},err}
 examples:=make([]NativeTextExample,len(xs));for i,x:=range xs{examples[i]=NativeTextExample{x.Input,labels[i]}}
 m,err:=TrainNativeTextSelector(examples);if err!=nil{return nativeGeneratorField{},err}
 raw,err:=m.Checkpoint();return nativeGeneratorField{Kind:"native",Model:raw},err
}
func readGeneratorField(f nativeGeneratorField,text string)(int,[]float64,error){
 if f.Kind=="constant"{return f.Value,[]float64{},nil}
 m,err:=RestoreNativeTextSelector(f.Model);if err!=nil{return 0,nil,err}
 p,err:=m.Predict(text);if err!=nil{return 0,nil,err}
 n,err:=strconv.Atoi(p.Response);return n,p.NativeScores,err
}
func TrainNativeParallelGenerator(xs []NativeTextExample)(*NativeParallelGenerator,error){
 if len(xs)<2||len(xs)>8{return nil,ErrNativeSession}
 width,total:=0,0
 hashes:=map[string]bool{}
 for _,x:=range xs{
  if !nativeTextValid(x.Input,128)||!nativeTextValid(x.Response,16){return nil,ErrNativeSession}
  total+=len(x.Input);width=max(width,len(x.Response));hashes[generatorDigest([]byte(x.Response))]=true
 }
 if total>512{return nil,ErrNativeSession}
 labels:=make([][]string,width*8);variable:=false
 for field:=range labels{
  labels[field]=make([]string,len(xs))
  for i,x:=range xs{value:=byte(0);if field/8<len(x.Response){value=x.Response[field/8]};labels[field][i]=strconv.Itoa(int((value>>uint(field%8))&1))}
  for _,x:=range labels[field]{if x!=labels[field][0]{variable=true}}
 }
 if !variable{return nil,ErrNativeSession}
 // Validate all input and limits before any native training.
 m:=&NativeParallelGenerator{width:width,exampleCount:len(xs),inputBytes:total}
 raw,err:=json.Marshal(xs);if err!=nil{return nil,err};m.trainingSHA=generatorDigest(raw)
 for h:=range hashes{m.responseHashes=append(m.responseHashes,h)};sort.Strings(m.responseHashes)
 lengths:=make([]string,len(xs));for i,x:=range xs{lengths[i]=strconv.Itoa(len(x.Response))}
 m.length,err=trainGeneratorField(xs,lengths);if err!=nil{return nil,err}
 for _,ys:=range labels{f,err:=trainGeneratorField(xs,ys);if err!=nil{return nil,err};m.fields=append(m.fields,f)}
 if !m.valid(){return nil,ErrNativeSession};return m,nil
}
func (m *NativeParallelGenerator) valid()bool{
 if m==nil||m.width<1||m.width>16||m.exampleCount<2||m.exampleCount>8||m.inputBytes<m.exampleCount||m.inputBytes>min(512,128*m.exampleCount)||!generatorDigestValid(m.trainingSHA)||len(m.fields)!=m.width*8||len(m.responseHashes)<2||len(m.responseHashes)>m.exampleCount{return false}
 for i,h:=range m.responseHashes{if !generatorDigestValid(h)||(i>0&&m.responseHashes[i-1]>=h){return false}}
 fieldValid:=func(f nativeGeneratorField,isLength bool)bool{
  if f.Kind=="constant"{if len(f.Model)!=0{return false};if isLength{return f.Value==m.width};return f.Value==0||f.Value==1}
  if f.Kind!="native"||f.Value!=0||len(f.Model)==0||len(f.Model)>65536{return false}
  model,err:=RestoreNativeTextSelector(f.Model);if err!=nil{return false}
  if !isLength{return len(model.responses)==2&&model.responses[0]=="0"&&model.responses[1]=="1"}
  foundMax:=false
  for _,r:=range model.responses{n,err:=strconv.Atoi(r);if err!=nil||n<1||n>m.width||strconv.Itoa(n)!=r{return false};if n==m.width{foundMax=true}}
  return foundMax
 }
 if !fieldValid(m.length,true){return false}
 native:=false
 for _,f:=range m.fields{if !fieldValid(f,false){return false};if f.Kind=="native"{native=true}}
 return native
}
func (m *NativeParallelGenerator) Generate(text string)(NativeGenerationResult,error){
 if !nativeTextValid(text,128)||!m.valid(){return NativeGenerationResult{},ErrNativeSession}
 length,lengthScores,err:=readGeneratorField(m.length,text);if err!=nil{return NativeGenerationResult{},err}
 raw:=make([]byte,m.width);scores:=make([][]float64,len(m.fields))
 for i,f:=range m.fields{value,score,err:=readGeneratorField(f,text);if err!=nil{return NativeGenerationResult{},err};raw[i/8]|=byte(value)<<uint(i%8);scores[i]=score}
 lengthValid:=length>=1&&length<=m.width
 candidate:=raw;if lengthValid{candidate=raw[:length]}
 validUTF8:=utf8.Valid(candidate);valid:=lengthValid&&validUTF8
 result:=NativeGenerationResult{RawHex:hex.EncodeToString(candidate),PredictedLength:length,LengthValid:lengthValid,UTF8Valid:validUTF8,ValidOutput:valid,CandidateStatus:"INVALID_GENERATED_CANDIDATE",OutputMode:"parallel-native-byte-field",LengthScores:lengthScores,BitScores:scores}
 if valid{s:=string(candidate);result.Response=&s;result.CandidateStatus="VALID_UTF8"}
 hash:=generatorDigest(candidate);for _,h:=range m.responseHashes{if h==hash{result.SeenTrainingResponse=true}}
 return result,nil
}
func (m *NativeParallelGenerator) Checkpoint()([]byte,error){
 if !m.valid(){return nil,ErrNativeSession}
 p:=nativeGeneratorPayload{nativeGeneratorSchema,NativeSessionSource,nativeGeneratorSelector,nativeGeneratorEncoding,m.width,m.exampleCount,m.inputBytes,m.trainingSHA,m.responseHashes,m.length,m.fields}
 raw,err:=json.Marshal(p);if err!=nil{return nil,err}
 out,err:=json.Marshal(nativeGeneratorEnvelope{p,generatorDigest(raw)});if err!=nil||len(out)>NativeGeneratorJSONCap{return nil,ErrNativeSession};return out,nil
}
// ValidateNativeGeneratorJSON extends the bounded protocol to larger complete
// field checkpoints without changing the earlier session/text request limits.
func ValidateNativeGeneratorJSON(raw []byte)error{
 if len(raw)==0||len(raw)>NativeGeneratorJSONCap{return ErrNativeSession}
 d:=json.NewDecoder(bytes.NewReader(raw));d.UseNumber()
 var visit func(int)error
 visit=func(depth int)error{
  if depth>32{return ErrNativeSession}
  tok,err:=d.Token();if err!=nil||tok==nil{return ErrNativeSession}
  if delim,ok:=tok.(json.Delim);ok{
   switch delim{
   case '{':
    seen:=map[string]bool{};for d.More(){key,err:=d.Token();k,ok:=key.(string);if err!=nil||!ok||seen[k]{return ErrNativeSession};seen[k]=true;if visit(depth+1)!=nil{return ErrNativeSession}}
    end,err:=d.Token();if err!=nil||end!=json.Delim('}'){return ErrNativeSession}
   case '[':
    for d.More(){if visit(depth+1)!=nil{return ErrNativeSession}};end,err:=d.Token();if err!=nil||end!=json.Delim(']'){return ErrNativeSession}
   default:return ErrNativeSession
   }
  }
  return nil
 }
 if visit(0)!=nil{return ErrNativeSession};if _,err:=d.Token();err!=io.EOF{return ErrNativeSession};return nil
}
func RestoreNativeParallelGenerator(raw []byte)(*NativeParallelGenerator,error){
 if ValidateNativeGeneratorJSON(raw)!=nil{return nil,ErrNativeSession}
 var envelope nativeGeneratorEnvelope;d:=json.NewDecoder(bytes.NewReader(raw));d.DisallowUnknownFields()
 if d.Decode(&envelope)!=nil||d.Decode(new(any))!=io.EOF{return nil,ErrNativeSession}
 p:=envelope.Payload
 if p.Schema!=nativeGeneratorSchema||p.SourceBlob!=NativeSessionSource||p.SelectorBlob!=nativeGeneratorSelector||p.Encoding!=nativeGeneratorEncoding{return nil,ErrNativeSession}
 payload,err:=json.Marshal(p);if err!=nil||envelope.SHA256!=generatorDigest(payload){return nil,ErrNativeSession}
 m:=&NativeParallelGenerator{p.Width,p.ExampleCount,p.InputBytes,p.TrainingSHA,p.ResponseHashes,p.Length,p.Fields}
 if !m.valid(){return nil,ErrNativeSession};return m,nil
}
